-- T0B-13.C16 schema suite: engagement catalogue properties (C16 05-SCHEMA §1, §3, §4, §5, §6, §7, §8; AC-0B-2.1, 2.2, 2.3, 2.4, 3.1, 3.2, 3.3, 3.4, 3.5, 3.6, 3.7, 4.1, 4.2, 4.3, 5.1, 5.2, 5.3, 6.1, 6.2, 6.3, 6.4).
-- Pure pg_catalog assertions: no fixtures, no data written. One rolled-back transaction. RLS is never disabled.
-- Run from the repo root: pg_prove -d <db> db/tests/engagement/T0B-13.C16_schema.test.sql   (pgTAP in schema `extensions`; migrations + seeds loaded; superuser). NOT run in the unit-test environment (no database).
-- Markers (the node test checks them): C16 check 1 inventory / owner, 2 RLS ENABLE+FORCE (G exempt), 3 policy set + DELETE policies + owner policies, 4 grants, 5 indexes / constraints / FKs, 6 triggers + functions + audit,
-- 7 DEFINER inventory + FK direction (AC-0B-6.1 / 6.2 / 6.3), 8 views + seeds (AC-0B-6.4). The six FORCE-RLS tests of §6.6 live in T-A2 / T-A3 / T-L2 / T-Q3 / T-OPS1 / T-SEC1 of this directory.
-- Scope: engagement.event_inbox is C0's (T0B-05) and excluded from every count. lims_api / lims_worker INHERIT lims_app, so "no DELETE" is asserted for lims_app only.
-- ACs: AC-0B-2.1 AC-0B-2.2 AC-0B-2.3 AC-0B-2.4 AC-0B-3.1 AC-0B-3.2 AC-0B-3.3 AC-0B-3.4 AC-0B-3.5 AC-0B-3.6 AC-0B-3.7 AC-0B-4.1 AC-0B-4.2 AC-0B-4.3 AC-0B-5.1 AC-0B-5.2 AC-0B-5.3 AC-0B-6.1 AC-0B-6.2 AC-0B-6.3 AC-0B-6.4
-- (2.x RLS/policies: checks 2-3; 3.x tenant isolation structure: checks 2, 5 + generated probes; 4.x grants/immutability: checks 4, 6; 5.x audit: check 6; 6.x order/FK/owner/views: checks 1, 7, 8)
BEGIN;
SET search_path = extensions, public, pg_catalog;
SELECT * FROM no_plan();

-- t: table; cls: §1 class; u: lims_app UPDATE; d: lims_app DELETE (class E tables of §1 only); aud: audit trigger (class M / C)
CREATE TEMP TABLE rt(t, cls, u, d, aud) AS VALUES
  ('settings','M',true,false,true),('accounts','M',true,false,true),('otp_challenges','E',true,true,false),('link_codes','E',true,true,false),('link_consents','A',false,false,false),('account_patient_links','M',true,false,true),
  ('self_registrations','E',true,false,false),('addresses','M',true,false,true),('bookable_items','M',true,false,true),('booking_centres','E',true,false,false),('slot_templates','M',true,false,true),('slot_blackouts','M',true,false,true),
  ('slot_occupancy','M',true,false,true),('bookings','C',true,false,true),('booking_items','A',false,false,false),('booking_transitions','A',false,false,false),('patient_orders','E',true,true,false),('patient_order_specimens','E',true,true,false),
  ('patient_reports','E',true,true,false),('smart_summaries','E',true,true,false),('notifications','E',true,true,false),('payment_requests','M',true,false,true),('queue_definitions','M',true,false,true),('queue_counters','M',true,false,true),
  ('queue_day_counters','M',true,false,true),('queue_tokens','C',true,false,true),('queue_displays','M',true,false,true),('reminders','M',true,false,true),('membership_plans','M',true,false,true),('patient_memberships','M',true,false,true),
  ('number_counters','E',true,true,false),('enquiries','M',true,false,true),('enquiry_messages','A',false,false,false),('cs_booking_cancel_reasons','M',true,false,true),('cs_reminder_reasons','M',true,false,true),('cs_enquiry_categories','M',true,false,true);
CREATE TEMP TABLE rg(t) AS VALUES ('g_cs_booking_cancel_reasons'),('g_cs_reminder_reasons'),('g_cs_enquiry_categories');
CREATE TEMP TABLE rd(f, args, execs, bad) AS VALUES   -- DEFINER inventory (§6.6): function, argument types (LD-230 (5): ::regprocedure rejects parameter names), the one EXECUTE role, a role that must not execute
  ('app.engagement_account_id','','lims_app','lims_api'),('app.engagement_patient_ids','','lims_app','lims_api'),('app.engagement_patient_visible','uuid, timestamp with time zone','lims_app','lims_api'),
  ('app.engagement_redeem_link_code','bytea','lims_app','lims_api'),('app.engagement_apply_report_link','uuid, timestamp with time zone','lims_app','lims_api'),
  ('app.engagement_code_redeemed_by_me','uuid, uuid','lims_app','lims_api'),('app.engagement_resolve_preauth','text, bytea','lims_api','lims_app'),
  ('app.engagement_resolve_display','bytea','lims_api','lims_app'),('engagement.purge_payment_requests','','lims_worker','lims_app'),('engagement.purge_queue','','lims_worker','lims_app');

-- C16 check 1: inventory, owner (AC-0B-1.2, AC-0B-6.3), schema privileges, no sequences / enums
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'engagement'::regnamespace AND c.relkind IN ('r','p')), 36 + 3 + 1, 'C16 check 1: engagement holds 36 tenant + 3 G tables + event_inbox (39 chunk tables = 05-SCHEMA §3 count of table statements)');
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'engagement'::regnamespace AND relkind IN ('r','p') AND relname <> 'event_inbox'), (SELECT array_agg(t ORDER BY t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x), 'C16 check 1: the table set equals the §3 inventory');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'engagement'::regnamespace AND c.relkind = 'm'), 0, 'C16 check 1: no materialized view');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'engagement'::regnamespace AND c.relkind = 'S'), 0, 'C16 check 1: no sequences');
SELECT is((SELECT count(*)::int FROM pg_type t WHERE t.typnamespace = 'engagement'::regnamespace AND t.typtype = 'e'), 0, 'C16 check 1: no ENUM types');
SELECT is(pg_get_userbyid(c.relowner), 'lims_owner', 'C16 check 1: engagement.' || c.relname || ' owned by lims_owner (AC-0B-1.2, AC-0B-6.3)') FROM pg_class c WHERE c.relnamespace = 'engagement'::regnamespace AND c.relkind IN ('r','p','v');
SELECT is(has_schema_privilege('lims_app', 'engagement', 'USAGE'), true, 'C16 check 1: lims_app has USAGE on schema engagement');
SELECT is(has_schema_privilege(r, 'engagement', 'CREATE'), false, 'C16 check 1: ' || r || ' cannot CREATE in engagement') FROM unnest(ARRAY['lims_app','lims_api','lims_worker','lims_analytics']) r;

-- C16 check 2: RLS ENABLE + FORCE on the 36 tenant tables, none on the 3 G tables (AC-0B-2.1, 2.4)
SELECT is((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid = ('engagement.' || t)::regclass), true, 'C16 check 2 / AC-0B-2.1: ENABLE + FORCE RLS on engagement.' || t) FROM rt;
SELECT is((SELECT relrowsecurity OR relforcerowsecurity FROM pg_class WHERE oid = ('engagement.' || t)::regclass), false, 'C16 check 2 / AC-0B-2.1: engagement.' || t || ' is RLS-exempt (global coded set, listed in rls_exempt.txt)') FROM rg;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename = g.t), 0, 'C16 check 2: no policy on ' || g.t) FROM rg g;
SELECT is(NOT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'engagement'::regnamespace AND relkind = 'r' AND relname NOT LIKE 'g\_%' AND NOT (relrowsecurity AND relforcerowsecurity)), true, 'C16 check 2 / AC-0B-2.4: every non-G engagement table (incl. event_inbox) has ENABLE + FORCE RLS');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'engagement' AND column_name = 'tenant_id' AND is_nullable = 'YES'), 0, 'C16 check 2 / AC-0B-3.5: tenant_id is NOT NULL everywhere');

-- C16 check 3: policies (AC-0B-2.3): 13 owner policies TO lims_owner; DELETE policies only on the 8 class E tables, system actor only; staff guard (P-16); tenant predicate; no open predicate
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_owner']::name[]), 13, 'C16 check 3 / §6.5: 13 owner policies TO lims_owner');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND roles <> ARRAY['lims_app']::name[] AND policyname !~ '__owner_only$'), 0, 'C16 check 3: every non-lims_app policy is an __owner_only policy');
SELECT is((SELECT array_agg(tablename::text || '.' || cmd ORDER BY tablename::text) FROM pg_policies WHERE schemaname = 'engagement' AND roles = ARRAY['lims_app']::name[] AND cmd = 'DELETE'), (SELECT array_agg('' || t || '.DELETE' ORDER BY t) FROM rt WHERE d), 'C16 check 3 / P-18(c): lims_app DELETE policies exactly on the 8 class E tables with a DELETE grant');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND roles = ARRAY['lims_app']::name[] AND cmd = 'DELETE' AND qual !~ '''system''::text'), 0, 'C16 check 3: every lims_app DELETE policy admits only the system actor');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename = rt.t AND cmd = 'UPDATE' AND roles = ARRAY['lims_app']::name[]) > 0, u, 'C16 check 3: UPDATE policy on engagement.' || t || ' iff a lims_app UPDATE grant exists') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_tenant_id%'), 0, 'C16 check 3: tenant predicate in every lims_app policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '''user''::text, ''system''::text\)' AND (coalesce(qual, '') || coalesce(with_check, '')) NOT LIKE '%is_staff_or_system%'), 0, 'C16 check 3 / P-16: every staff policy carries app.is_staff_or_system()');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(^|[ (])true($|[ )])' ), 0, 'C16 check 3 / REQ-SEC-016: no USING (true)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'current_centre_ids' AND (coalesce(qual, '') || coalesce(with_check, '')) !~ 'uuid\[\]'), 0, 'C16 check 3 / 08 A16.1: every centre predicate uses the ::uuid[] cast');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND policyname !~ ('^' || tablename || '__(select|insert|update|delete)__[a-z_]+$')), 0, 'C16 check 3: policy names are <table>__<cmd>__<scope>');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND policyname !~ ('__' || lower(cmd) || '__')), 0, 'C16 check 3: the command in the policy name matches the policy command');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'engagement' AND policyname = 'otp_challenges__select__owner_only'), 'token_sha256 = decode\(current_setting\(''app\.pre_engagement_otp_token_sha256''::text, true\), ''hex''::text\)', 'C16 check 3 / A12.1: pre-tenant owner policy USING = decode(current_setting(GUC)) only');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'engagement' AND policyname = 'queue_displays__select__owner_only'), 'token_sha256 = decode\(current_setting\(''app\.pre_engagement_display_token_sha256''::text, true\), ''hex''::text\)', 'C16 check 3 / A12.1: display owner policy USING = decode(current_setting(GUC)) only');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'engagement' AND policyname = 'queue_tokens__delete__owner_only'), 'engagement_purge_queue', 'C16 check 3 / A12.2: purge owner policies are gated by the app.maintenance GUC');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'engagement' AND policyname = 'link_codes__delete__tenant'), 'account_patient_links', 'C16 check 3 / §5.3 note: link_codes DELETE keeps codes referenced by a link');

-- C16 check 4: grant matrix (AC-0B-4.2 / 4.3; §1 column): S I U everywhere except class A (S I); D only on the 8 class E tables; S on G; CI assertion has_table_privilege(...,'DELETE') = false elsewhere
SELECT is(ARRAY[has_table_privilege('lims_app', 'engagement.' || t, 'SELECT'), has_table_privilege('lims_app', 'engagement.' || t, 'INSERT'), has_table_privilege('lims_app', 'engagement.' || t, 'UPDATE'), has_table_privilege('lims_app', 'engagement.' || t, 'DELETE')],
  ARRAY[true, true, u, d], 'C16 check 4 / AC-0B-4.1 / 4.2: lims_app privileges on engagement.' || t || ' = §1 (S I' || CASE WHEN u THEN ' U' ELSE '' END || CASE WHEN d THEN ' D' ELSE '' END || ')') FROM rt;
SELECT is(ARRAY[has_table_privilege('lims_app', 'engagement.' || t, 'SELECT'), has_table_privilege('lims_app', 'engagement.' || t, 'INSERT'), has_table_privilege('lims_app', 'engagement.' || t, 'UPDATE'), has_table_privilege('lims_app', 'engagement.' || t, 'DELETE')],
  ARRAY[true, false, false, false], 'C16 check 4 / AC-0B-4.3: lims_app only SELECTs engagement.' || t) FROM rg;
SELECT is(has_table_privilege('lims_app', 'engagement.' || t, 'TRUNCATE') OR has_table_privilege('lims_app', 'engagement.' || t, 'REFERENCES') OR has_table_privilege('lims_app', 'engagement.' || t, 'TRIGGER'), false, 'C16 check 4: no TRUNCATE / REFERENCES / TRIGGER on engagement.' || t) FROM rt;
SELECT is(has_table_privilege('lims_analytics', 'engagement.' || x.t, p), false, 'C16 check 4: lims_analytics has no ' || p || ' on engagement.' || x.t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT is((SELECT count(*)::int FROM information_schema.role_table_grants WHERE table_schema = 'engagement' AND grantee IN ('PUBLIC','anon','authenticated','service_role')), 0, 'C16 check 4: nothing granted to PUBLIC / anon / authenticated / service_role');

-- C16 check 5: indexes and constraints (§2.2 rule 9, §3): tenant_id leads every index except the primary keys, G tables and queue_displays__token__uq; __p_ indexes partial; UNIQUE (tenant_id, id) where an id exists; tenant FK everywhere; composite FKs
SELECT is((regexp_match(pg_get_indexdef(i.indexrelid), '\(([^,)]+)'))[1], 'tenant_id', 'C16 check 5: index ' || c.relname || ' leads with tenant_id')
  FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid
  WHERE t.relnamespace = 'engagement'::regnamespace AND t.relname NOT LIKE 'g\_%' AND t.relname <> 'event_inbox' AND NOT i.indisprimary AND c.relname <> 'queue_displays__token__uq';
SELECT is((SELECT pg_get_indexdef(indexrelid) ~ '\(token_sha256\)' FROM pg_index WHERE indexrelid = 'engagement.queue_displays__token__uq'::regclass AND indisunique), true, 'C16 check 5 / CR-C16-006: queue_displays UNIQUE (token_sha256) is the one non-tenant-leading unique (pre-tenant resolver lookup)');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'engagement' AND indexname ~ '__p_(uq|idx)$' AND indexdef NOT LIKE '% WHERE %'), 0, 'C16 check 5: every __p_ index is partial');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'engagement' AND tablename <> 'event_inbox' AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE connamespace = 'engagement'::regnamespace)), 46, 'C16 check 5: exactly the 46 spec indexes beyond the constraint-backed ones (no extra index)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('engagement.' || t)::regclass AND contype = 'u' AND pg_get_constraintdef(oid) = 'UNIQUE (tenant_id, id)'), 1, 'C16 check 5 / 04 D8: UNIQUE (tenant_id, id) on engagement.' || t)
  FROM rt WHERE EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = ('engagement.' || t)::regclass AND attname = 'id' AND NOT attisdropped);
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('engagement.' || t)::regclass AND contype = 'f' AND confrelid = 'core.tenants'::regclass AND pg_get_constraintdef(oid) = 'FOREIGN KEY (tenant_id) REFERENCES core.tenants(id)'), 1, 'C16 check 5 / C0 §9 rule 1: tenant FK -> core.tenants on engagement.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'engagement'::regnamespace AND relname NOT LIKE 'g\_%' AND relname <> 'event_inbox')
  AND cardinality(c.conkey) = 1 AND c.confrelid <> 'core.tenants'::regclass), 0, 'C16 check 5: every FK except the tenant FK is composite (tenant_id, x) (02-CV §5.4)');
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = ('engagement.' || t)::regclass AND attname = 'id' AND NOT attisdropped), 0, 'C16 check 5 / §1 P-18(b): engagement.' || t || ' has no id column (natural-key PK)') FROM unnest(ARRAY['patient_orders','patient_order_specimens','patient_reports','queue_day_counters','number_counters']) t;
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'engagement.g_cs_reminder_reasons'::regclass AND attnum > 0 AND NOT attisdropped), (SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'engagement.g_cs_booking_cancel_reasons'::regclass AND attnum > 0 AND NOT attisdropped), 'C16 check 5: LIKE copies carry the same columns');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = 'engagement.g_cs_enquiry_categories'::regclass AND contype = 'p'), 1, 'C16 check 5: LIKE ... INCLUDING ALL copied the primary key (code)');

-- C16 check 6: triggers, functions, audit (AC-0B-4.1, 5.1, 5.2, 5.3): 7 spec triggers, 3 INVOKER guards, 22 audit triggers (class M / C), Secret columns excluded from audit
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('engagement.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgname = t || '__audit' AND tg.tgfoid = 'app.tg_row_audit'::regproc), CASE WHEN aud THEN 1 ELSE 0 END, 'C16 check 6 / AC-0B-5.1: audit trigger on engagement.' || t || ' iff class M / C') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'engagement'::regnamespace) AND NOT tg.tgisinternal AND tg.tgname LIKE '%\_\_audit'), 22, 'C16 check 6 / AC-0B-5.3: 22 audit triggers (20 class M + 2 class C); none on class A / E / G');
SELECT matches((SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid = x.t::regclass AND tgname = split_part(x.t, '.', 2) || '__audit'), x.col, 'C16 check 6 / §10: ' || x.t || ' audit trigger excludes the Secret column ' || x.col)
  FROM (VALUES ('engagement.queue_displays','token_sha256'),('engagement.patient_memberships','card_token'),('engagement.payment_requests','action_json')) x(t, col);
SELECT is((SELECT array_agg(tgname::text ORDER BY tgname::text) FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'engagement'::regnamespace) AND NOT tgisinternal AND tgname NOT LIKE '%\_\_audit' AND tgrelid <> 'engagement.event_inbox'::regclass),
  ARRAY['account_patient_links__mutable_columns','account_patient_links__patient_guard','bookings__mutable_columns','queue_displays__device_guard','queue_tokens__mutable_columns','settings__consent_version','slot_occupancy__patient_guard'], 'C16 check 6: exactly the 7 spec triggers by name (immutability of the C tables bookings / queue_tokens, AC-0B-4.1)');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = ('engagement.' || x.t)::regclass AND tgname = x.n AND (tgtype & 2) = 2 AND (tgtype & 16) = 16 AND (tgtype & 1) = 1), 1, 'C16 check 6: ' || x.n || ' is BEFORE UPDATE FOR EACH ROW')
  FROM (VALUES ('settings','settings__consent_version'),('account_patient_links','account_patient_links__mutable_columns'),('account_patient_links','account_patient_links__patient_guard'),('bookings','bookings__mutable_columns'),('queue_tokens','queue_tokens__mutable_columns'),('slot_occupancy','slot_occupancy__patient_guard'),('queue_displays','queue_displays__device_guard')) x(t, n);
SELECT is((SELECT tgfoid::regproc::text FROM pg_trigger WHERE tgrelid = 'engagement.bookings'::regclass AND tgname = 'bookings__mutable_columns'), 'app.enforce_mutable_columns', 'C16 check 6: bookings uses the C0 immutability trigger');
SELECT is((SELECT prosecdef FROM pg_proc WHERE pronamespace = 'engagement'::regnamespace AND proname = f), false, 'C16 check 6 / AC-0B-4.1 / 04 D7: engagement.' || f || ' is SECURITY INVOKER (no inventory row)') FROM unnest(ARRAY['settings_consent_version_guard','guard_actor_columns','guard_patient_link_update']) f;
SELECT is((SELECT proconfig FROM pg_proc WHERE pronamespace = 'engagement'::regnamespace AND proname = f), ARRAY['search_path=""'], 'C16 check 6: engagement.' || f || ' has search_path = empty') FROM unnest(ARRAY['settings_consent_version_guard','guard_actor_columns','guard_patient_link_update']) f;
SELECT is((SELECT array_agg(proname::text ORDER BY proname::text) FROM pg_proc WHERE pronamespace = 'engagement'::regnamespace), ARRAY['guard_actor_columns','guard_patient_link_update','purge_payment_requests','purge_queue','settings_consent_version_guard'], 'C16 check 6: functions in schema engagement = 3 guards + 2 purge DEFINERs');

-- C16 check 7: DEFINER inventory, EXECUTE ACLs, FK direction (AC-0B-6.1 / 6.2 / 6.3; REQ-SEC-031, REQ-SEC-020)
SELECT is((SELECT count(*)::int FROM pg_proc WHERE oid = (f || '(' || args || ')')::regprocedure AND prosecdef AND pg_get_userbyid(proowner) = 'lims_owner' AND proconfig = ARRAY['search_path=""']), 1, 'C16 check 7 / AC-0B-6.3: ' || f || ' is SECURITY DEFINER, owned by lims_owner, search_path = empty') FROM rd;
SELECT is(has_function_privilege(execs, (f || '(' || args || ')')::regprocedure, 'EXECUTE'), true, 'C16 check 7 / §6.6: ' || execs || ' may EXECUTE ' || f) FROM rd;
SELECT is(has_function_privilege(bad, (f || '(' || args || ')')::regprocedure, 'EXECUTE'), false, 'C16 check 7 / 08 A12.1: ' || bad || ' may NOT execute ' || f) FROM rd WHERE execs <> 'lims_app';
SELECT is((SELECT coalesce(proacl::text, '') ~ '(^\{|,)=X' FROM pg_proc WHERE oid = (f || '(' || args || ')')::regprocedure), false, 'C16 check 7: EXECUTE revoked from PUBLIC on ' || f) FROM rd;
SELECT is((SELECT count(*)::int FROM pg_proc WHERE prosecdef AND ((pronamespace = 'app'::regnamespace AND proname LIKE 'engagement_%') OR pronamespace = 'engagement'::regnamespace)), 10, 'C16 check 7: exactly 10 DEFINER functions of C16 (matches the 10 inventory rows)');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'app'::regnamespace AND proname = 'engagement_resolve_tenant_code'), 0, 'C16 check 7 / D-121: engagement_resolve_tenant_code is removed (C0 app.core_resolve_tenant_code resolves it)');
SELECT is((SELECT array_agg(DISTINCT n.nspname::text ORDER BY n.nspname::text) FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'engagement'::regnamespace)),
  ARRAY['core','engagement','frontdesk'], 'C16 check 7 / AC-0B-6.2: engagement FKs point into engagement, core, frontdesk only (01 §5 R3)');
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid WHERE c.contype = 'f' AND r.relnamespace = 'engagement'::regnamespace AND c.conrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'engagement'::regnamespace)), 0, 'C16 check 7 / AC-0B-6.2: nothing references engagement from another schema');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'engagement'::regnamespace AND c.relkind = 'r' AND c.relname IN (SELECT t FROM rt)), 36, 'C16 check 7 / AC-0B-6.1: all 36 tenant tables exist after the migrations applied in order');

-- C16 check 8: views (AC-0B-6.4; IC §6) and seeds (§8)
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'engagement'::regnamespace AND relkind = 'v'), ARRAY['v_pub_booking_daily','v_pub_queue_daily'], 'C16 check 8 / AC-0B-6.4: exactly the two published views (the CR-C16-012 address / membership views are not created, 08 R25)');
SELECT is((SELECT reloptions FROM pg_class WHERE oid = ('engagement.' || v)::regclass), ARRAY['security_invoker=true'], 'C16 check 8: engagement.' || v || ' is WITH (security_invoker = true)') FROM unnest(ARRAY['v_pub_booking_daily','v_pub_queue_daily']) v;
SELECT is((SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid = 'engagement.v_pub_booking_daily'::regclass AND attnum > 0 AND NOT attisdropped), ARRAY['tenant_id','centre_id','business_date','booking_kind','created_via','bookings','completed','no_shows','cancelled'], 'C16 check 8 / AC-0B-6.4: v_pub_booking_daily columns = IC §6 (names + order)');
SELECT is((SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid = 'engagement.v_pub_queue_daily'::regclass AND attnum > 0 AND NOT attisdropped), ARRAY['tenant_id','centre_id','queue_id','business_date','tokens_issued','tokens_completed','tokens_not_served','median_wait_seconds','p90_wait_seconds'], 'C16 check 8 / AC-0B-6.4: v_pub_queue_daily columns = IC §6 (names + order)');
SELECT is(has_table_privilege('lims_app', 'engagement.' || v, 'SELECT'), true, 'C16 check 8: lims_app SELECT on engagement.' || v) FROM unnest(ARRAY['v_pub_booking_daily','v_pub_queue_daily']) v;
SELECT is(has_table_privilege('lims_app', 'engagement.' || v, 'INSERT') OR has_table_privilege('lims_app', 'engagement.' || v, 'UPDATE') OR has_table_privilege('lims_app', 'engagement.' || v, 'DELETE'), false, 'C16 check 8: engagement.' || v || ' is read-only for lims_app') FROM unnest(ARRAY['v_pub_booking_daily','v_pub_queue_daily']) v;
SELECT is((SELECT count(*)::int FROM engagement.g_cs_booking_cancel_reasons), 5, 'C16 check 8 / §8: 5 booking cancel reasons seeded');
SELECT is((SELECT count(*)::int FROM engagement.g_cs_reminder_reasons), 4, 'C16 check 8 / §8: 4 reminder reasons seeded');
SELECT is((SELECT count(*)::int FROM engagement.g_cs_enquiry_categories), 5, 'C16 check 8 / §8: 5 enquiry categories seeded');
SELECT is((SELECT array_agg(code ORDER BY code) FROM engagement.g_cs_booking_cancel_reasons), ARRAY['duplicate','lab_unavailable','no_show','patient_request','slot_expired'], 'C16 check 8 / §8: cancel reason codes');
SELECT is((SELECT count(*)::int FROM engagement.g_cs_booking_cancel_reasons WHERE NOT is_active) + (SELECT count(*)::int FROM engagement.g_cs_reminder_reasons WHERE NOT is_active) + (SELECT count(*)::int FROM engagement.g_cs_enquiry_categories WHERE NOT is_active), 0, 'C16 check 8: seed rows active');
SELECT is((SELECT count(*)::int FROM engagement.settings) + (SELECT count(*)::int FROM engagement.accounts) + (SELECT count(*)::int FROM engagement.bookings) + (SELECT count(*)::int FROM engagement.queue_tokens), 0, 'C16 check 8 / §8: no tenant data seeded by the migrations (fixtures belong to packages/test-fixtures)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'storage' AND policyname LIKE 'engagement%'), 0, 'C16 check 8: no storage policy is created by SQL');

